BEGIN;
SET LOCAL client_min_messages = notice;
SELECT test_assert(to_regclass('public.client_dependents') IS NOT NULL, 'dependent table exists');
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claim.sub = '00000000-0000-0000-0000-0000000000a0';
INSERT INTO public.client_dependents(id,user_id,client_id,name) VALUES
 ('40000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001','Dependente Fictício A');
SELECT test_assert((SELECT count(*)=1 FROM client_dependents),'owner inserts and selects');
UPDATE client_dependents SET nickname='Apelido Fictício',notes='Observação fictícia' WHERE id='40000000-0000-0000-0000-000000000001';
SELECT test_assert((SELECT nickname='Apelido Fictício' FROM client_dependents LIMIT 1),'owner updates');
SELECT test_denied($q$INSERT INTO client_dependents(user_id,client_id,name) VALUES ('00000000-0000-0000-0000-0000000000b0','10000000-0000-0000-0000-000000000003','Outro Fictício')$q$,'42501','owner cannot write another tenant');
SELECT test_denied($q$INSERT INTO client_dependents(user_id,client_id,name) VALUES ('00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000003','Outro Fictício')$q$,'23503','holder must belong to dependent tenant');
SELECT test_denied($q$UPDATE client_dependents SET user_id='00000000-0000-0000-0000-0000000000b0' $q$,'42501','owner cannot transfer tenant');
SELECT test_denied($q$INSERT INTO client_dependents(user_id,client_id,name) VALUES ('00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001',' dependente fictício a ')$q$,'23505','active names unique after trim and lower');
SELECT test_denied($q$INSERT INTO client_dependents(user_id,client_id,name) VALUES ('00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001',' ')$q$,'23514','empty name rejected');
SELECT test_denied($q$INSERT INTO client_dependents(user_id,client_id,name) VALUES ('00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001',repeat('x',81))$q$,'23514','oversized name rejected');
SELECT test_denied($q$INSERT INTO client_dependents(user_id,client_id,name,nickname) VALUES ('00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001','Pessoa',repeat('x',41))$q$,'23514','oversized nickname rejected');
SELECT test_denied($q$INSERT INTO client_dependents(user_id,client_id,name,notes) VALUES ('00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001','Pessoa',repeat('x',501))$q$,'23514','oversized notes rejected');
SELECT test_denied($q$INSERT INTO appointments(user_id,client_id,dependent_id,appointment_time) VALUES ('00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000002','40000000-0000-0000-0000-000000000001','2030-11-01 10:00Z')$q$,'23503','appointment rejects another holder dependent');
INSERT INTO appointments(id,user_id,client_id,dependent_id,appointment_time) VALUES
 ('50000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','2030-11-01 10:00Z');
UPDATE client_dependents SET name='Dependente Renomeado Fictício' WHERE id='40000000-0000-0000-0000-000000000001';
SELECT test_assert((SELECT attendee_name='Dependente Fictício A' FROM appointments WHERE id='50000000-0000-0000-0000-000000000001'),'rename preserves snapshot');
UPDATE appointments SET attendee_name='Nome Adulterado' WHERE id='50000000-0000-0000-0000-000000000001';
SELECT test_assert((SELECT attendee_name='Dependente Fictício A' FROM appointments WHERE id='50000000-0000-0000-0000-000000000001'),'snapshot immutable on unrelated edit');
SET LOCAL request.jwt.claim.sub = '00000000-0000-0000-0000-0000000000a1';
SELECT test_assert((SELECT count(*)=1 FROM client_dependents),'staff reads company dependents');
INSERT INTO client_dependents(id,user_id,client_id,name) VALUES
 ('40000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001','Dependente Fictício Staff');
WITH changed AS (UPDATE client_dependents SET name='Editado' RETURNING id) SELECT test_assert((SELECT count(*)=0 FROM changed),'staff cannot update');
WITH changed AS (DELETE FROM client_dependents RETURNING id) SELECT test_assert((SELECT count(*)=0 FROM changed),'staff cannot delete');
SELECT test_denied($q$INSERT INTO client_dependents(user_id,client_id,name) VALUES ('00000000-0000-0000-0000-0000000000b0','10000000-0000-0000-0000-000000000003','Outro')$q$,'42501','staff cannot insert cross tenant');
SELECT test_assert((create_internal_attendee_bookings('00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','2030-11-02 10:00Z','[{"dependent_id":"40000000-0000-0000-0000-000000000001","service_ids":["30000000-0000-0000-0000-000000000001"]},{"dependent_id":"40000000-0000-0000-0000-000000000002","service_ids":["30000000-0000-0000-0000-000000000001"]}]')->>'success')::boolean,'staff can schedule only dependents atomically');
SELECT test_assert((SELECT count(*)=2 AND min(client_id::text)=max(client_id::text) AND max(appointment_time)-min(appointment_time)=interval '20 minutes' FROM appointments WHERE appointment_time::date='2030-11-02'),'consecutive appointments keep holder and server duration');
SELECT test_denied($q$SELECT create_internal_attendee_bookings('00000000-0000-0000-0000-0000000000b0','10000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000001','2030-11-02 10:00Z','[]')$q$,'42501','RPC rejects cross tenant');
SELECT test_denied($q$SELECT create_internal_attendee_bookings('00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','2030-11-05 10:00Z','[{"service_ids":["30000000-0000-0000-0000-000000000002"]}]')$q$,'P0001','RPC rejects services from another tenant');
SELECT test_denied($q$SELECT create_internal_attendee_bookings('00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','2030-11-05 10:00Z','[{"service_ids":["30000000-0000-0000-0000-000000000001"]},{"service_ids":["30000000-0000-0000-0000-000000000001"]}]')$q$,'P0001','RPC rejects duplicate person');
SELECT test_denied($q$SELECT create_internal_attendee_bookings('00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','2030-11-05 10:00Z','[]')$q$,'P0001','RPC requires at least one person');
SELECT test_denied($q$SELECT create_internal_attendee_bookings('00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','2030-11-05 10:00Z','[{"dependent_id":"40000000-0000-0000-0000-000000000002","service_ids":[],"total_price":-1,"custom_service_name":"Serviço Fictício"}]')$q$,'P0001','RPC rejects negative price');
SET LOCAL request.jwt.claim.sub = '00000000-0000-0000-0000-0000000000b0';
SELECT test_assert((SELECT count(*)=0 FROM client_dependents),'another tenant sees no dependent');
WITH changed AS (UPDATE client_dependents SET name='Outro' RETURNING id) SELECT test_assert((SELECT count(*)=0 FROM changed),'another tenant cannot update');
WITH changed AS (DELETE FROM client_dependents RETURNING id) SELECT test_assert((SELECT count(*)=0 FROM changed),'another tenant cannot delete');
SET LOCAL request.jwt.claim.sub = '00000000-0000-0000-0000-0000000000a0';
INSERT INTO appointments(user_id,client_id,professional_id,appointment_time,duration_minutes) VALUES ('00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','2030-11-03 10:25Z',20);
SELECT test_assert(NOT (create_internal_attendee_bookings('00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','2030-11-03 10:00Z','[{"dependent_id":null,"service_ids":["30000000-0000-0000-0000-000000000001"]},{"dependent_id":"40000000-0000-0000-0000-000000000002","service_ids":["30000000-0000-0000-0000-000000000001"]}]')->>'success')::boolean,'late conflict refuses whole sequence');
SELECT test_assert((SELECT count(*)=1 FROM appointments WHERE appointment_time::date='2030-11-03'),'late conflict rolls back first appointment');
RESET ROLE;
INSERT INTO agenda_blocks(user_id,professional_id,starts_at,ends_at) VALUES ('00000000-0000-0000-0000-0000000000a0','20000000-0000-0000-0000-000000000001','2030-11-06 10:25Z','2030-11-06 11:00Z');
SET LOCAL ROLE authenticated;
SELECT test_assert(NOT (create_internal_attendee_bookings('00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','2030-11-06 10:00Z','[{"dependent_id":null,"service_ids":["30000000-0000-0000-0000-000000000001"]},{"dependent_id":"40000000-0000-0000-0000-000000000002","service_ids":["30000000-0000-0000-0000-000000000001"]}]')->>'success')::boolean,'late agenda block refuses sequence');
SELECT test_assert((SELECT count(*)=0 FROM appointments WHERE appointment_time::date='2030-11-06'),'late agenda block rolls back whole sequence');
UPDATE appointments SET status='Completed' WHERE appointment_time::date='2030-11-02';
SELECT test_assert((SELECT count(*)=2 AND sum(price)=60 FROM appointments WHERE client_id='10000000-0000-0000-0000-000000000001' AND status='Completed'),'one visit per attended person with holder LTV');
UPDATE client_dependents SET is_active=false WHERE id='40000000-0000-0000-0000-000000000001';
SELECT test_assert((SELECT attendee_name='Dependente Fictício A' FROM appointments WHERE id='50000000-0000-0000-0000-000000000001'),'archiving preserves history');
SELECT test_denied($q$INSERT INTO appointments(user_id,client_id,dependent_id,appointment_time) VALUES ('00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','2030-11-04 10:00Z')$q$,'23503','inactive dependent cannot be scheduled');
DELETE FROM client_dependents WHERE id='40000000-0000-0000-0000-000000000001';
SELECT test_assert((SELECT dependent_id IS NULL AND attendee_name='Dependente Fictício A' FROM appointments WHERE id='50000000-0000-0000-0000-000000000001'),'deleting dependent preserves snapshot and holder');
SET LOCAL ROLE anon;
SET LOCAL request.jwt.claim.sub = '';
SELECT test_denied('SELECT * FROM client_dependents','42501','anon cannot read');
SELECT test_denied($q$INSERT INTO client_dependents(user_id,client_id,name) VALUES ('00000000-0000-0000-0000-0000000000a0','10000000-0000-0000-0000-000000000001','Pessoa')$q$,'42501','anon cannot insert');
SELECT test_denied('UPDATE client_dependents SET name=''Pessoa''','42501','anon cannot update');
SELECT test_denied('DELETE FROM client_dependents','42501','anon cannot delete');
SELECT test_assert(NOT has_function_privilege('anon','public.create_internal_attendee_bookings(uuid,uuid,uuid,timestamptz,jsonb,text)','EXECUTE'),'anon cannot execute internal RPC');
ROLLBACK;
